function nordic(field: string, arm: string, w: number, h: number, thick: number, vx: number): string {
  return (
    rect(0, 0, w, h, field) +
    rect(vx, 0, thick, h, arm) +
    rect(0, (h - thick) / 2, w, thick, arm)
