};

type MeshBlob = [x: string, y: string, size: string, color: string];

function meshCss(blobs: MeshBlob[]): string {
  return blobs.map(([x, y, size, color]) => `radial-gradient(${size} at ${x} ${y}, ${color} 0%, transparent 70%)`).join(", ");
