// ---------------------------------------------------------------------------
// Initials avatars. Deterministic from a name, so the same person gets the
// same colour on every page and across rebuilds.
// ---------------------------------------------------------------------------

/** FNV-1a. Small, stable, and good enough to spread names across a hue wheel. */
function hash(input: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h;
}

/** Up to two initials: "Ada Lovelace" -> "AL", "cheryl" -> "C". */
export function initialsOf(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return "?";
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
  return (words[0][0] + words[words.length - 1][0]).toUpperCase();
}

export type AvatarColors = { from: string; to: string; text: string };

/**
 * A deterministic two-stop colour pair for a name. Saturation and lightness
 * are fixed so every avatar in a list has the same weight — only the hue moves.
 */
export function avatarColors(name: string): AvatarColors {
  const h = hash(name.toLowerCase());
  const hue = h % 360;
  // Skip the 55-90deg band, where mid-lightness yellows go muddy against white text.
  const safeHue = hue > 55 && hue < 90 ? hue + 40 : hue;
  return {
    from: `hsl(${safeHue} 62% 52%)`,
    to: `hsl(${(safeHue + 28) % 360} 58% 40%)`,
    text: "#ffffff",
  };
}

export type AvatarOptions = {
  size?: number;
  /** "circle" (default) or "rounded". */
  shape?: "circle" | "rounded";
  className?: string;
};

/** An inline `<svg>` initials avatar — no image, no request, no layout shift. */
export function initialsAvatarSvg(name: string, opts: AvatarOptions = {}): string {
  const { size = 64, shape = "circle", className } = opts;
  const { from, to, text } = avatarColors(name);
  const initials = initialsOf(name);
  // The gradient id must be unique per name so two avatars on one page don't
  // collide — SVG gradient ids are document-global.
  const gid = `av${hash(name).toString(36)}`;
  const bg =
    shape === "circle"
      ? `<circle cx="32" cy="32" r="32" fill="url(#${gid})"/>`
      : `<rect width="64" height="64" rx="16" fill="url(#${gid})"/>`;
  const cls = className ? ` class="${className}"` : "";
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="${size}" height="${size}"` +
    ` role="img" aria-label="${name.replace(/[<>&"]/g, "")}"${cls}>` +
    `<defs><linearGradient id="${gid}" x1="0" y1="0" x2="1" y2="1">` +
    `<stop offset="0%" stop-color="${from}"/><stop offset="100%" stop-color="${to}"/></linearGradient></defs>` +
    bg +
    `<text x="32" y="33" text-anchor="middle" dominant-baseline="central" fill="${text}"` +
    ` font-family="ui-sans-serif, system-ui, -apple-system, Segoe UI, sans-serif" font-size="${
      initials.length > 1 ? 26 : 30
    }" font-weight="600" letter-spacing="0.5">${initials}</text></svg>`
  );
}

/**
 * The CSS-only form: a gradient background plus the initials as text. Cheaper
 * than the SVG when the avatar is already a React element.
 */
export function initialsAvatarCss(name: string): { css: string; initials: string } {
  const { from, to, text } = avatarColors(name);
  return {
    initials: initialsOf(name),
    css: `background-image: linear-gradient(135deg, ${from}, ${to}); color: ${text};`,
  };
}

/**
 * The asset library's front door: one catalogue and one query function over
 * every inlinable asset Kodely can hand a generated site.
 *
 * THE SEAM
 * {@link findAssets} is deliberately shaped like a tool call. A future agent
 * tool ("search_assets") should be able to forward its arguments straight
 * through and hand the model back `AssetMatch[]` — each match already carries
 * a paste-ready `source` and a one-line `usage`, so the model never has to
 * invent SVG geometry or guess at a CSS incantation. Wiring that tool into
 * lib/agent.ts is not this module's job; being callable from it is.
 *
 * WHY EVERY MATCH IS INLINABLE
 * Generated sites run under `default-src 'self'; img-src 'self' data:;
 * connect-src 'none'` with no way to add npm packages, so a hosted asset —
 * however convenient — would fail silently at serve time. Every `source`
 * string here is either markup, CSS, or a `data:` URI, all of which survive
 * that sandbox. See the header comments in ./icons.ts and ./patterns.ts.
 */

import {
  ICONS,
  iconCategories,
  iconDataUri,
  iconJsx,
  iconSvg,
  type Icon,
  type IconWeight,
} from "./icons";
import { FLAGS, flagSvg, type Flag } from "./flags";
import {
  DIVIDERS,
  GRADIENTS,
  MESHES,
  PATTERNS,
  TEXTURES,
  avatarColors,
  dividerSvg,
  initialsAvatarSvg,
  initialsOf,
} from "./patterns";

export type AssetKind = "icon" | "flag" | "gradient" | "mesh" | "texture" | "divider" | "pattern" | "avatar";

export const ASSET_KINDS: AssetKind[] = [
  "icon",
  "flag",
  "gradient",
  "mesh",
  "texture",
  "divider",
  "pattern",
  "avatar",
];

export type AssetMatch = {
  /** Stable, namespaced: "icon:phone", "flag:fr", "gradient:sunset". */
  id: string;
  kind: AssetKind;
  name: string;
  keywords: string[];
  format: "jsx" | "svg" | "css" | "text";
  /** The thing to paste into the generated site. */
  source: string;
  /** One line telling the caller where this goes. */
  usage: string;
  /** Alternative representations — raw svg, data URI, Tailwind class, colours. */
  variants?: Record<string, string>;
  /** Relevance for the query that produced this. 0 when listed rather than searched. */
  score: number;
};

export type FindAssetsOptions = {
  /** Restrict to one or more kinds. Omit for everything. */
  kind?: AssetKind | AssetKind[];
  /** Default 20, capped at 100. */
  limit?: number;
  /** Icon stroke weight for the emitted `source`. Default "regular". */
  weight?: IconWeight;
};

// ---------------------------------------------------------------------------
// Catalogue
// ---------------------------------------------------------------------------

type Entry = {
  id: string;
  kind: AssetKind;
  name: string;
  /** Lowercased, de-duplicated search terms. */
  keywords: string[];
  render: (opts: FindAssetsOptions) => Pick<AssetMatch, "format" | "source" | "usage" | "variants">;
};

function iconEntry(icon: Icon): Entry {
  return {
    id: `icon:${icon.id}`,
    kind: "icon",
    name: icon.name,
    keywords: icon.keywords,
    render: (opts) => ({
      format: "jsx",
      source: iconJsx(icon.id, { weight: opts.weight ?? "regular", size: null, className: "h-6 w-6" }) ?? "",
      usage:
        "Paste inline into a .tsx file. Stroke is currentColor, so set the colour with a Tailwind text-* class on the icon or its parent; size with h-*/w-*.",
      variants: {
        svg: iconSvg(icon.id, { weight: opts.weight ?? "regular" }) ?? "",
        dataUri: iconDataUri(icon.id, { weight: opts.weight ?? "regular" }) ?? "",
        category: icon.category,
      },
    }),
  };
}

function flagEntry(flag: Flag): Entry {
  const kw = [
    flag.code,
    ...flag.name.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),
    "flag",
    "country",
    "nation",
    ...(flag.svg ? ["svg"] : ["emoji"]),
  ];
  return {
    id: `flag:${flag.code}`,
    kind: "flag",
    name: flag.name,
    keywords: kw,
    render: () => {
      const svg = flag.svg ? flagSvg(flag.code, { width: 60 }) : null;
      if (svg) {
        return {
          format: "svg",
          source: svg,
          usage:
            flag.svg?.accuracy === "simplified"
              ? `Hand-authored SVG. SIMPLIFIED: ${flag.svg.note ?? "detail omitted"} — use the emoji instead if exactness matters.`
              : "Hand-authored SVG, accurate to the flag's construction. Paste inline; run it through toJsx() for a .tsx file.",
          variants: { emoji: flag.emoji, code: flag.code, accuracy: flag.svg?.accuracy ?? "" },
        };
      }
      return {
        format: "text",
        source: flag.emoji,
        usage:
          "Emoji flag — plain text, works with no asset at all. Note that Windows Chrome/Edge render these as two letter boxes, not a flag.",
        variants: { code: flag.code },
      };
    },
  };
}

function buildCatalog(): Entry[] {
  const entries: Entry[] = [];

  for (const icon of ICONS) entries.push(iconEntry(icon));
  for (const flag of FLAGS) entries.push(flagEntry(flag));

  for (const g of GRADIENTS) {
    entries.push({
      id: `gradient:${g.id}`,
      kind: "gradient",
      name: g.name,
      keywords: g.keywords,
      render: () => ({
        format: "css",
        source: `background-image: ${g.css};`,
        usage: `Tailwind: className="${g.tailwind}". Or set background-image in a style block. Colours: ${g.colors.join(", ")}.`,
        variants: { tailwind: g.tailwind, gradient: g.css, colors: g.colors.join(","), family: g.family },
      }),
    });
  }

  for (const m of MESHES) {
    entries.push({
      id: `mesh:${m.id}`,
      kind: "mesh",
      name: m.name,
      keywords: m.keywords,
      render: () => ({
        format: "css",
        source: `background-color: ${m.base}; background-image: ${m.css};`,
        usage: "A layered radial-gradient background. Put it on the section itself; it scales to any viewport with no image.",
        variants: { base: m.base, image: m.css },
      }),
    });
  }

  for (const t of TEXTURES) {
    entries.push({
      id: `texture:${t.id}`,
      kind: "texture",
      name: t.name,
      keywords: t.keywords,
      render: () => ({ format: "css", source: t.css, usage: t.note }),
    });
  }

  for (const d of DIVIDERS) {
    entries.push({
      id: `divider:${d.id}`,
      kind: "divider",
      name: d.name,
      keywords: d.keywords,
      render: () => ({
        format: "svg",
        source: dividerSvg(d.id, { fill: "currentColor", height: 90 }) ?? "",
        usage:
          "Sit it at the bottom of a section (position it absolutely, or just place it last with display:block). Colour it with a text-* class matching the NEXT section's background.",
        variants: { path: d.d, flipped: dividerSvg(d.id, { fill: "currentColor", flipY: true }) ?? "" },
      }),
    });
  }

  for (const p of PATTERNS) {
    entries.push({
      id: `pattern:${p.id}`,
      kind: "pattern",
      name: p.name,
      keywords: p.keywords,
      render: () => ({
        format: "css",
        source: p.css,
        usage:
          "Pure CSS — no image and no request. The default ink is rgba(0,0,0,.08); rebuild with a different colour/scale via getPattern(id).build(color, size).",
      }),
    });
  }

  entries.push({
    id: "avatar:initials",
    kind: "avatar",
    name: "Initials avatar",
    keywords: [
      "avatar",
      "initials",
      "placeholder",
      "profile",
      "person",
      "team",
      "testimonial",
      "user",
      "photo",
      "headshot",
      "portrait",
      "staff",
    ],
    render: () => {
      const sample = "Ada Lovelace";
      const { from, to } = avatarColors(sample);
      return {
        format: "svg",
        source: initialsAvatarSvg(sample, { size: 64 }),
        usage:
          "Deterministic from the name: same person, same colour, every build. Generate per name with initialsAvatarSvg(name) — or use initialsAvatarCss(name) and render the initials as text. This is the honest stand-in for a headshot; the sandbox has no photography.",
        variants: { initials: initialsOf(sample), from, to },
      };
    },
  });

  return entries;
}

const CATALOG: Entry[] = buildCatalog();
const BY_ID = new Map(CATALOG.map((e) => [e.id, e]));

