// ---- stats ----
const files = ["icons.ts", "flags.ts", "patterns.ts", "index.ts"];
let total = 0;
for (const f of files) {
  const s = statSync(ROOT + "lib/assets/" + f).size;
  total += s;
  console.log(`lib/assets/${f}: ${(s / 1024).toFixed(1)} KB`);
}
const routeSize = statSync(ROOT + "app/api/assets/route.ts").size;
console.log(`app/api/assets/route.ts: ${(routeSize / 1024).toFixed(1)} KB`);
console.log(`TOTAL SOURCE: ${((total + routeSize) / 1024).toFixed(1)} KB`);

const summary = index.assetCatalogSummary();
console.log("\nSUMMARY", JSON.stringify(summary, null, 1));

// runtime footprint of the rendered catalog
const all = index.listAssets();
const bytes = all.reduce((n, a) => n + a.source.length + JSON.stringify(a.variants ?? {}).length, 0);
console.log(`\nRendered catalog: ${all.length} assets, ${(bytes / 1024).toFixed(1)} KB of source strings`);

// ---- search smoke tests ----
const queries = [
  "coffee", "phone", "instagram", "plumber", "dentist", "hairdresser",
  "france", "flag of japan", "sunset gradient", "wave divider", "dot pattern",
  "avatar placeholder", "star rating", "shopping cart", "grain texture",
  "restaurant menu", "zzzznope",
];
console.log("\n--- search ---");
for (const q of queries) {
  const r = index.findAssets(q, { limit: 4 });
  console.log(`${q.padEnd(20)} -> ${r.map((m) => `${m.id}(${m.score.toFixed(1)})`).join(", ") || "(none)"}`);
}

console.log("\nkind filter icon:", index.findAssets("blue", { kind: "gradient", limit: 3 }).map((m) => m.id));
console.log("getAsset:", index.getAsset("icon:phone")?.source.slice(0, 90));
console.log("bad id:", index.getAsset("icon:nope"));
console.log("empty query:", index.findAssets("", { kind: "divider", limit: 3 }).map((m) => m.id));

// ---- duplicate id check ----
const ids = all.map((a) => a.id);
const dupes = ids.filter((id, i) => ids.indexOf(id) !== i);
console.log("duplicate ids:", dupes.length ? dupes : "none");

// ---- malformed svg check ----
const bad = [];
for (const icon of icons.ICONS) {
  const svg = icons.iconSvg(icon.id);
  if (!svg.includes("</svg>")) bad.push(icon.id + ": unclosed");
  // every path d must start with M/m and contain only path grammar chars
  for (const m of icon.body.matchAll(/ d="([^"]*)"/g)) {
    const d = m[1];
    if (!/^[Mm]/.test(d)) bad.push(icon.id + ": d does not start with M -> " + d.slice(0, 20));
    if (/[^MmLlHhVvCcSsQqTtAaZz0-9.,\-\s]/.test(d)) bad.push(icon.id + ": bad char in d");
    if (/\d\.\d*\./.test(d)) bad.push(icon.id + ": malformed number in d");
  }
}
console.log("icon path issues:", bad.length ? bad : "none");

const badFlags = [];
for (const f of flags.flagsWithSvg()) {
  const svg = flags.flagSvg(f.code);
  if (!svg || !svg.includes("</svg>")) badFlags.push(f.code);
  if (/NaN|undefined|Infinity/.test(svg)) badFlags.push(f.code + ": NaN/undefined");
}
console.log("flag issues:", badFlags.length ? badFlags : "none");

// emoji coverage
const noEmoji = flags.FLAGS.filter((f) => !f.emoji);
console.log("flags total:", flags.FLAGS.length, "| with svg:", flags.flagsWithSvg().length, "| missing emoji:", noEmoji.length);
console.log("emoji sample:", flags.getFlag("fr").emoji, flags.getFlag("jp").emoji, flags.getFlag("za").emoji);

// ---- html preview ----
const iconGrid = icons.ICONS.map(
  (i) =>
    `<figure><div class="ic">${icons.iconSvg(i.id, { size: 32 })}</div><figcaption>${i.id}</figcaption></figure>`,
).join("");
const iconWeights = ["light", "regular", "bold"]
  .map((w) => `<div class="row">${["phone", "star", "heart", "cart" in {} ? "" : "shopping-cart", "check", "scissors"].map((id) => icons.iconSvg(id, { size: 40, weight: w })).join("")}<span>${w}</span></div>`)
  .join("");
const flagGrid = flags
  .flagsWithSvg()
  .map((f) => `<figure><div class="fl">${flags.flagSvg(f.code, { width: 84 })}</div><figcaption>${f.code} ${f.svg.accuracy === "simplified" ? "*" : ""}</figcaption></figure>`)
  .join("");
const gradGrid = patterns.GRADIENTS.map(
  (g) => `<figure><div class="sw" style="background-image:${g.css}"></div><figcaption>${g.id}</figcaption></figure>`,
).join("");
const meshGrid = patterns.MESHES.map(
  (m) => `<figure><div class="sw" style="background-color:${m.base};background-image:${m.css}"></div><figcaption>${m.id}</figcaption></figure>`,
