const texGrid = patterns.TEXTURES.map(
  (t) => `<figure><div class="sw" style="background:#5b7bd5;${t.css}"></div><figcaption>${t.id}</figcaption></figure>`,
).join("");
const patGrid = patterns.PATTERNS.map(
